         // is reported about the returned (absent) frame.
         match result {
             Ok(frame) => {
                 &&& frame.inv()
                 &&& phys_view().frames.allocated_frames.contains(frame@)
                 &&& phys_view().frames.refcounts.contains_key(frame@)
                 &&& phys_view().frames.refcounts[frame@] == 1
             },
             Err(_) => true,
         },
